insert into public.venues (id, name, kind, quartier_id, address, status, verification, data_origin, opening_hours, admission, free_when, visit_tips, info_checked_on) values ('b247d1c8-8e28-5974-b124-1317bc6a5d9c', 'Naturhistorisches Museum der Universität Zürich', 'Museum', (select q.id from public.quartiers q join public.districts d on d.id = q.district_id where d.city_id = 'zurich' and q.name = 'Hochschulen'), 'Karl-Schmid-Strasse 4, 8006 Zürich', 'published', 'provider_verified', 'provider:site', 'Di–So 10–17 Uhr · Donnerstagabend 17.30–20 Uhr (nur für Erwachsene) · Montag geschlossen. Geschlossen: 24.–26.12., 31.12.–2.1., Ostermontag, Pfingstmontag, 1. Mai, 1. August.', 'Eintritt frei (eine Spende in die «Exit-Pricing-Box» ist erwünscht).', 'Immer gratis.', 'Kinder unter 12 Jahren haben nur in Begleitung Erwachsener Zutritt. Wegen der begrenzten Platzverhältnisse bittet das Museum, wenn möglich auf Kinderwagen und grössere Kindertransportmittel zu verzichten. Familienworkshops: siehe Website.', '2026-11-18') on conflict (id) do update set opening_hours = excluded.opening_hours, admission = excluded.admission, free_when = excluded.free_when, visit_tips = excluded.visit_tips, info_checked_on = excluded.info_checked_on;
