insert into public.source_links (source_id, role, venue_id) select id, 'organiser', 'b247d1c8-8e28-5974-b124-1317bc6a5d9c' from public.sources where url = 'https://www.nmz.uzh.ch/de/besucherinformation.html' on conflict do nothing;
insert into public.venues (id, name, kind, quartier_id, address, status, verification, data_origin, opening_hours, admission, free_when, visit_tips, info_checked_on) values ('e5045c3f-7605-53cd-a187-00038417582b', 'Kulturama – Museum des Menschen', 'Museum', (select q.id from public.quartiers q join public.districts d on d.id = q.district_id where d.city_id = 'zurich' and q.name = 'Hottingen'), 'Englischviertelstrasse 9, 8032 Zürich', 'published', 'provider_verified', 'provider:site', 'Di, Do, Fr 13–17 Uhr · Mi 13–20 Uhr · Sa, So 13–18 Uhr.', 'Erwachsene CHF 14 · Kinder und Jugendliche 6–16 Jahre CHF 9. Ein Preis für jüngere Kinder ist auf der Website nicht aufgeführt: bitte beim Museum nachfragen.', 'Freier Eintritt gegen Vorweisen bestimmter Karten (Liste auf kulturama.ch/besuchen).', 'Für einen ruhigen Besuch empfiehlt das Museum Dienstag bis Freitag am späteren Nachmittag, Mittwochabend bis 20 Uhr oder schönes Wetter. Im Eintritt inbegriffen: Entdeckungstour und Parcours für Kinder (selbständig).', '2026-11-18') on conflict (id) do update set opening_hours = excluded.opening_hours, admission = excluded.admission, free_when = excluded.free_when, visit_tips = excluded.visit_tips, info_checked_on = excluded.info_checked_on;
insert into public.sources (id, url) values ('657aec6b-56d8-5129-9f98-d30d32c547fb', 'https://www.kulturama.ch/besuchen/') on conflict (url) do nothing;
