insert into public.venues (id, name, kind, quartier_id, address, status, verification, data_origin, opening_hours, admission, free_when, visit_tips, info_checked_on) values ('14782401-5433-5acb-a21b-d35c49f7e83f', 'NONAM – Nordamerika Native Museum', 'Museum', (select q.id from public.quartiers q join public.districts d on d.id = q.district_id where d.city_id = 'zurich' and q.name = 'Mühlebach'), 'Seefeldstrasse 317, 8008 Zürich', 'published', 'provider_verified', 'provider:site', 'Di–Sa 13–17 Uhr · So 10–17 Uhr · Montag geschlossen. Im November 2026 nur am Wochenende geöffnet (Di–Fr geschlossen wegen Aufbau der neuen Sonderausstellung; 30 % Rabatt auf den Eintritt). Geschlossen am Pfingstmontag.', 'Erwachsene CHF 17 (ermässigt 9) · Kinder 6–18 Jahre CHF 6 · Familien CHF 30. Ein Preis für Kinder unter 6 Jahren ist auf der Website nicht aufgeführt.', null, 'Haltestelle Wildbachstrasse empfohlen. Bauarbeiten an der Seefeldstrasse können die Anreise erschweren.', '2026-11-18') on conflict (id) do update set opening_hours = excluded.opening_hours, admission = excluded.admission, free_when = excluded.free_when, visit_tips = excluded.visit_tips, info_checked_on = excluded.info_checked_on;
