insert into public.venues (id, name, kind, quartier_id, address, status, verification, data_origin, opening_hours, admission, free_when, visit_tips, info_checked_on) values ('003c8cdb-d672-545b-b2c7-78ae3d3fe0f2', 'Zoo Zürich', 'Zoo', (select q.id from public.quartiers q join public.districts d on d.id = q.district_id where d.city_id = 'zurich' and q.name = 'Fluntern'), 'Zürichbergstrasse 221, 8044 Zürich', 'published', 'provider_verified', 'provider:site', 'März bis Oktober 9–18 Uhr (Masoala Regenwald 10–18 Uhr) · November bis Februar 9–17 Uhr (Masoala Regenwald 10–17 Uhr). Am 24. Dezember schliesst der Zoo um 16 Uhr.', 'Preise für Tageseintritt und Jahreskarte: siehe zoo.ch/zoobesuch/tickets-preise (auf der Website laufend aktualisiert). IV-Beziehende und Kulturlegi-Inhabende erhalten reduzierte Preise an der Tageskasse.', null, 'Gruppen ab 10 Personen haben separate Preise und Bedingungen.', '2026-11-18') on conflict (id) do update set opening_hours = excluded.opening_hours, admission = excluded.admission, free_when = excluded.free_when, visit_tips = excluded.visit_tips, info_checked_on = excluded.info_checked_on;
